def classify_cell(grid, R, C):
    """Classify each cell based on the pattern we observed"""
    result = {}
    for r in range(R):
        for c in range(C):
            cell = grid[r][c]
            if cell == 1:
                result[(r,c)] = '1'
            elif cell == 0:
                # Check orthogonal 1 neighbors
                has_orth_1 = False
                if r > 0 and grid[r-1][c] == 1:
                    has_orth_1 = True
                if r < R-1 and grid[r+1][c] == 1:
                    has_orth_1 = True
                if c > 0 and grid[r][c-1] == 1:
                    has_orth_1 = True
                if c < C-1 and grid[r][c+1] == 1:
                    has_orth_1 = True

                if has_orth_1:
                    result[(r,c)] = '0_adj_1'  # adjacent to 1
                else:
                    result[(r,c)] = '0_no_orth_1'  # not adjacent to any 1
    return result

