# Look for 30x30 grids
def find_30x30_infodata():
    found = []
    for f in os.listdir(task_dir):
        path = os.path.join(task_dir, f)
        if not os.path.isfile(path):
            continue
        with open(path, 'r') as fp:
            try:
                data = json.load(fp)
            except:
                continue

        # Check if it's a list of 30x30 grids
        if isinstance(data, list):
            for i, entry in enumerate(data[:10]):  # Check first 10 entries
                if isinstance(entry, list) and len(entry) == 30 and len(entry) > 0 and isinstance(entry[0], list):
                    all_int = all(isinstance(x, int) for row in entry for x in row)
                    found.append((f, i, '30x30' if all_int else 'mixed'))
        # Check if it's a single grid
        elif isinstance(data, list) and len(data) == 30 and len(data) > 0 and isinstance(data[0], list):
            all_int = all(isinstance(x, int) for row in data for x in row)
            found.append((f, 0, '30x30' if all_int else 'mixed'))

        # Check if it's a dict with 'grid' key
        elif isinstance(data, dict) and 'grid' in data:
            grid = data['grid']
            if isinstance(grid, list) and len(grid) == 30 and len(grid) > 0 and isinstance(grid[0], list):
                all_int = all(isinstance(x, int) for row in grid for x in row)
                found.append((f, len(grid), '30x30' if all_int else 'mixed'))

    return found

found = find_30x30_infodata()
